const products = $('Fetch All Products').item.json || [];
const orders = $('Fetch Recent Sales').item.json || [];
const threshold = $('Set Store Config').item.json.low_stock_threshold;
const leadDays = $('Set Store Config').item.json.reorder_lead_days;

const salesVelocity = {};
orders.forEach(order => {
  (order.line_items||[]).forEach(item => {
    salesVelocity[item.product_id] = (salesVelocity[item.product_id]||0) + item.quantity;
  });
});

const alerts = [];
const reorderNeeded = [];

products.forEach(p => {
  const stock = p.stock_quantity || 0;
  const velocity = salesVelocity[p.id] || 0;
  const dailyVelocity = velocity / 30;
  const daysOfStock = dailyVelocity > 0 ? Math.floor(stock / dailyVelocity) : 999;

  if (stock <= threshold) {
    alerts.push({ name: p.name, id: p.id, stock, status: 'LOW STOCK', daily_velocity: dailyVelocity.toFixed(1), days_remaining: daysOfStock });
  } else if (daysOfStock <= leadDays) {
    reorderNeeded.push({ name: p.name, id: p.id, stock, status: 'REORDER SOON', daily_velocity: dailyVelocity.toFixed(1), days_remaining: daysOfStock });
  }
});

return [{ json: { low_stock: alerts, reorder_soon: reorderNeeded, total_products: products.length, total_alerts: alerts.length + reorderNeeded.length } }];

